SELECT
blrr.f_report_date
FROM
base_lithology_recognition_report blrr

    f_is_delete = '0'
    and blrr.f_project_section_id= #{fId}

        and blrr.f_report_date >= #{recognitonReportDto.timeStart}


        and blrr.f_report_date <= #{recognitonReportDto.timeEnd}


group by blrr.f_report_date
order by blrr.f_report_date desc

select *
from base_lithology_recognition_report

    f_is_delete = '0'

        and f_project_section_id = #{recognitionreport.fProjectSectionId}


        and f_create_user_id = #{recognitionreport.fUserId}


        and f_project_section_name like CONCAT('%',#{recognitionreport.fProjectSectionName},'%')


        and f_report_name like CONCAT('%',#{recognitionreport.fReportName},'%')


        and f_report_nike_name like CONCAT('%',#{recognitionreport.fReportNikeName},'%')

    and f_report_date = #{record}
    order by f_create_time desc

select *
from base_lithology_recognition_report

    f_is_delete = '0'

        and f_create_user_id = #{recognitionreport.fUserId}


        and f_project_section_id = #{recognitionreport.fProjectSectionId}


        and f_project_section_name = #{recognitionreport.fProjectSectionName}


        and f_report_name = #{recognitionreport.fReportName}


        and f_report_nike_name = #{recognitionreport.fReportNikeName}


        and f_report_date >= #{recognitionreport.timeStart}


        and f_report_date <= #{recognitionreport.timeEnd}
